// loops.cpp
constexpr auto SAMPLES = std::size_t{65536};
constexpr auto RUNS = std::size_t{100};

// Chandler Carruth, CppCon 2015: https://www.youtube.com/watch?v=nXaxk27zwlk
auto escape(void* p) -> void { asm volatile("" : : "g"(p) : "memory"); }

// Average ns per sample for median run of loop.
auto bench(auto loop) -> double
{
    using clock = std::chrono::steady_clock;
    auto ns = std::vector<double>(RUNS);
    for (auto& t : ns) {
        const auto start = clock::now();
        loop();  // SAMPLES iterations
        const auto elapsed = clock::now() - start;
        t = std::chrono::duration<double, std::nano>(elapsed).count();
    }
    std::ranges::sort(ns);
    return ns[RUNS / 2] / double(SAMPLES);
}

main:
auto main() -> int
{
    constexpr auto pi = std::numbers::pi_v<float>;
    auto rng = std::mt19937{1};
    auto dist = std::uniform_real_distribution<float>{-pi, pi};
    auto in = std::vector<float>(SAMPLES);
    auto out = std::vector<float>(SAMPLES);
    for (auto& x : in) x = dist(rng);
    std::ranges::sort(in);  // leave out for random

    const auto a = bench([](float x) { return std::sin(x); }, in, out);
    const auto b = bench([](float x) { return adc::taylor_sin_13(x); }, in, out);
    std::printf("std::sin %.2f ns\nTaylor   %.2f ns (%.1fx)\n", a, b, a / b);
}

cold:
// Read one word per cache line of a buffer far bigger than the caches.
auto evict() -> void
{
    static auto junk = std::vector<std::uint64_t>((64 << 20) / 8, 1);
    auto sum = std::uint64_t{};
    for (auto i = 0uz; i < junk.size(); i += 8) sum += junk[i];
    escape(&sum);
}

// Average ns per sample over BLOCK-sample callbacks, each right after an evict.
auto bench_cold(auto f, std::span<const float> in, std::span<float> out) -> double
{
    using clock = std::chrono::steady_clock;
    auto ns = std::vector<double>{};
    for (auto b = 0uz; b < in.size(); b += BLOCK) {
        evict();
        std::ranges::copy(in.subspan(b, BLOCK), &out[b]);  // the host's buffers are warm
        escape(out.data());
        const auto start = clock::now();
        for (auto i = b; i < b + BLOCK; ++i)
            out[i] = f(in[i]);
        escape(out.data());
        const auto elapsed = clock::now() - start;
        ns.push_back(std::chrono::duration<double, std::nano>(elapsed).count());
    }
    std::ranges::sort(ns);
    ns.resize(ns.size() * 9 / 10);  // drop the slowest 10%: interrupts
    return std::reduce(ns.begin(), ns.end()) / double(ns.size() * BLOCK);
}

loops:
// Buffer: the compiler may optimize within the buffer.
auto buffer(auto f, std::span<const float> in, std::span<float> out) -> void
{
    for (auto i = 0uz; i < in.size(); ++i)
        out[i] = f(in[i]);
    escape(out.data());
}

// Sample: the compiler may optimize within the sample.
auto sample(auto f, std::span<const float> in, std::span<float> out) -> void
{
    for (auto i = 0uz; i < in.size(); ++i) {
        out[i] = f(in[i]);
        escape(&out[i]);
    }
}

// Feedback: the previous output must be known.
auto feedback(auto f, std::span<const float> in) -> void
{
    auto y = 0.0f;
    for (auto i = 0uz; i < in.size(); ++i)
        y = f(in[i] + 0.0f * y);
    escape(&y);
}
